    readonly 'integrationsCatalog.entry.fellow.details': 'חברו את Fellow כדי שהסוכן יחפש בתמלולים, יחלץ תובנות מסיכומי פגישות ויעקוב אחר משימות להמשך.';
    readonly 'integrationsCatalog.entry.krisp.details': 'חברו את Krisp כדי שהסוכן יאתר את היסטוריית הפגישות שלכם, החלטות קודמות ומשימות להמשך.';
    readonly 'integrationsCatalog.entry.deepwiki.details': 'תנו לסוכן את DeepWiki: תיעוד שנוצר אוטומטית למאגרים ציבוריים ותשובות שמבוססות על הקוד שלהם. לא נדרש חשבון.';
