    readonly 'integrationsCatalog.entry.jam.details': 'חברו את Jam כדי שקישור Jam בשיחה יביא לסוכן את ההקלטה כולה: וידאו, קונסולה, בקשות רשת ולוגים, בלי להקליד מחדש את שלבי השחזור.';
    readonly 'integrationsCatalog.entry.statsig.details': 'חברו את Statsig כדי שהסוכן ייצור וישנה feature gates, הגדרות דינמיות וניסויים ויקרא את התוצאות שלהם. כולל את המיומנות של Statsig לעבודה עם gates, ניסויים והגדרות.';
    readonly 'integrationsCatalog.entry.devcycle.details': 'חברו את DevCycle כדי שהסוכן ייצור feature flags, יערוך טירגוט ומשתנים ויבדוק איך הדגלים מוערכים.';
