    readonly 'integrationsCatalog.entry.clerk.details': 'חברו את Clerk כדי שהסוכן יקבל קטעי SDK ודפוסים עדכניים להתחברות, סשנים, הגנה על נתיבים וארגונים.';
    readonly 'integrationsCatalog.entry.workos.details': 'חברו את WorkOS כדי שהסוכן יעבוד עם הסביבות, הארגונים, המשתמשים, חיבורי ה-SSO וסנכרון הספריות שלכם.';
    readonly 'integrationsCatalog.entry.stytch.details': 'חברו את Stytch כדי שהסוכן ינהל את הפרויקט שלכם: כתובות הפניה, תבניות אימייל, אסימונים ציבוריים ועוד.';
    readonly 'integrationsCatalog.entry.descope.details': 'חברו את Descope כדי שהסוכן יעבוד עם הפרויקט שלכם: משתמשים, דיירים, תפקידים והגדרות אימות.';
    readonly 'integrationsCatalog.entry.buf.details': 'חברו את Buf כדי שהסוכן יאתר מודולים, הגדרות Protobuf ו-gRPC והגרסאות שלהן ב-Buf Schema Registry.';
    readonly 'integrationsCatalog.entry.apollo-graphos.details': 'תנו לסוכן חיפוש בתיעוד של Apollo, את מפרט ה-Connectors וכלי GraphOS לסכמות, בדיקות והשקות. החיפוש בתיעוד לא דורש חשבון.';
